import './App.css';
import Signin from "./Online_Ticket_system/Signin";
import Footer from "./Online_Ticket_system/Footer";
import Admin from './Online_Ticket_system//Admin';
import User from './Online_Ticket_system//User';
import Header from './Online_Ticket_system//Header';

export default function App() {
  const [currentUser, setCurrentUser] = useState(null);

  // Callback when user signs in successfully
  const handleLoginSuccess = (userData) => {
    setCurrentUser(userData);
  };

  // Callback to log out
  const handleLogout = () => {
    setCurrentUser(null);
  };

  // 1. Unauthenticated View (Auth Page)
  if (!currentUser) {
    return <AuthPage onLoginSuccess={handleLoginSuccess} />;
  }

  // 2. Authenticated View (Header + Dashboard)
  return (
    <div style={styles.appWrapper}>
      <Header user={currentUser} onLogout={handleLogout} />

      <main style={styles.mainContent}>
        {currentUser.role === 'admin' ? (
          <Admin user={currentUser} />
        ) : (
          <User user={currentUser} />
        )}
      </main>
    </div>
  );
}

const styles = {
  appWrapper: {
    minHeight: '100vh',
    backgroundColor: '#18181b', // Ash/Dark background
    color: '#ffffff',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  mainContent: {
    padding: '24px',
    maxWidth: '1200px',
    margin: '0 auto',
  },
};
